def get_axioms() -> list:
    return []


def get_vars() -> dict:
    grad_output = TensorVar('grad_output')
    self = TensorVar('self')
    kernel_size = IntArrayVar('kernel_size')
    stride = IntArrayVar('stride')
    padding = IntArrayVar('padding')
    ceil_mode = Bool('ceil_mode')
    count_include_pad = Bool('count_include_pad')
    divisor_override = OptVar('divisor_override', Int('divisor_override' + '.val'))
    grad_input = TensorVar('grad_input')
    return {'grad_output': grad_output, 'self': self, 'kernel_size': kernel_size, 'stride': stride, 'padding': padding, 'ceil_mode': ceil_mode, 'count_include_pad': count_include_pad, 'divisor_override': divisor_override, 'grad_input': grad_input}


def build_solver() -> Solver:
    s = Solver()
    s.add(*get_axioms())
    return s


from mobile.generator.constraints.model import TensorVar, same_shape
def _out_shape_ok():
    self_ = TensorVar('self')
    gi = TensorVar('grad_input')
    return Or(gi.numel() == 0, same_shape(gi, self_))


def get_constraints() -> list:
    _base = _orig_get_constraints()
    _e = _base[0]
    _inner = _e.arg(0)
    if _inner.decl().name() == 'and':
        _parts = list(_inner.children())
    else:
        _parts = [_inner]
    return [Not(And(*_parts, _out_shape_ok()))]
